import React, { useState, useEffect } from "react";
import axios from "axios";
import { useNavigate, useLocation } from "react-router-dom";
import "bootstrap/dist/css/bootstrap.min.css";

const Home = () => {
  const [cursos, setCursos] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [user, setUser] = useState(null);
  const [comentarios, setComentarios] = useState([]);
  const [showComentarioModal, setShowComentarioModal] = useState(false);
  const [novoComentario, setNovoComentario] = useState("");
  const [nome, setNome] = useState("");
  const [email, setEmail] = useState("");
  const navigate = useNavigate();
  const location = useLocation();

  useEffect(() => {
    if (location.state?.message) {
      alert(location.state.message);
      navigate(location.pathname, { replace: true, state: {} });
    }

    const fetchCursos = async () => {
      try {
        const response = await axios.get("http://localhost:5000/cursos");
        setCursos(response.data);
        setLoading(false);
      } catch (err) {
        setError(err.message);
        setLoading(false);
      }
    };

    const fetchComentarios = async () => {
      try {
        const response = await axios.get("http://localhost:5000/comentarios");
        setComentarios(response.data);
      } catch (err) {
        console.error("Erro ao carregar comentários:", err);
      }
    };

    const checkAuth = () => {
      const token = localStorage.getItem("token");
      const userData = JSON.parse(localStorage.getItem("user"));
      if (token && userData) {
        setIsAuthenticated(true);
        setUser(userData);
      }
    };

    fetchCursos();
    fetchComentarios();
    checkAuth();
  }, [navigate, location]);

  const handleProtectedLink = (path) => {
    if (isAuthenticated) {
      navigate(path);
    } else {
      navigate("/login", {
        state: {
          from: path,
          message: "Por favor, faça login para acessar esta página",
        },
      });
    }
  };

  const handleComentarioClick = () => {
    setShowComentarioModal(true);
  };

  const handleSubmitComentario = async () => {
    if (!novoComentario.trim()) {
      alert("Por favor, escreva um comentário antes de enviar.");
      return;
    }

    if (!nome.trim() || !email.trim()) {
      alert("Por favor, preencha seu nome e e-mail.");
      return;
    }

    try {
      const response = await axios.post("http://localhost:5000/comentarios", {
        conteudo: novoComentario,
        nome,
        email,
      });

      setComentarios([response.data, ...comentarios]);
      setNovoComentario("");
      setNome("");
      setEmail("");
      setShowComentarioModal(false);
    } catch (err) {
      console.error("Erro ao enviar comentário:", err);
      alert("Erro ao enviar comentário. Por favor, tente novamente.");
    }
  };

  const cursosPorArea = cursos.reduce((acc, curso) => {
    if (!acc[curso.area]) {
      acc[curso.area] = [];
    }
    acc[curso.area].push(curso);
    return acc;
  }, {});

  if (loading) {
    return (
      <div className="container-fluid text-center mt-5">
        <div className="spinner-border" role="status">
          <span className="visually-hidden">Carregando...</span>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="container-fluid text-center mt-5">
        <div className="alert alert-danger">
          Erro ao carregar cursos: {error}
        </div>
      </div>
    );
  }

  return (
    <div
      className="container-fluid"
      style={{
        backgroundColor: "#F8F9FA",
        minHeight: "100vh",
        padding: "20px",
      }}
    >
      <nav className="d-flex justify-content-end p-3">
        <a href="." className="mx-2">
          Home
        </a>
        <a href="./about" className="mx-2">
          About
        </a>
        <a href="./faq" className="mx-2">
          Faq
        </a>
        <a href="./contact" className="mx-2">
          Contacto
        </a>
        {isAuthenticated ? (
          <button
            className="btn btn-link mx-2"
            onClick={() => {
              localStorage.removeItem("token");
              localStorage.removeItem("user");
              setIsAuthenticated(false);
              setUser(null);
              navigate("/");
            }}
          >
            Logout
          </button>
        ) : (
          <>
            <a href="./login" className="mx-2">
              Login
            </a>
            <a href="./register" className="mx-2">
              Registo
            </a>
          </>
        )}
      </nav>
      <h1>EducaWeb</h1>

      <div className="row mt-4">
        {Object.entries(cursosPorArea).map(([area, cursosDaArea]) => (
          <div className="col-md-6 mb-4" key={area}>
            <div className="card h-100">
              <div className="card-body">
                <h2 className="card-title">
                  {area} {getEmojiForArea(area)}
                </h2>
                <ul className="list-group list-group-flush">
                  {cursosDaArea.map((curso) => (
                    <li className="list-group-item" key={curso.id}>
                      <strong>{curso.nome}</strong>
                      <div className="text-muted small mt-1">
                        {curso.periodo} | Nível {curso.nivel}
                      </div>
                      <div className="text-muted small">
                        {formatDate(curso.dataInicio)} -{" "}
                        {formatDate(curso.dataFim)}
                      </div>
                    </li>
                  ))}
                </ul>
              </div>
            </div>
          </div>
        ))}
      </div>

      <div className="row mt-5">
        <div className="col-md-6 bg-white p-4 rounded shadow">
          <h4>Testemunhos dos utilizadores:</h4>
          {comentarios.length > 0 ? (
            comentarios.map((comentario) => (
              <div key={comentario.id} className="mb-3">
                <h5>{comentario.nome}:</h5>
                <p>{comentario.conteudo}</p>
                <small className="text-muted">
                  {new Date(comentario.dataPublicacao).toLocaleDateString(
                    "pt-PT",
                    {
                      day: "2-digit",
                      month: "2-digit",
                      year: "numeric",
                      hour: "2-digit",
                      minute: "2-digit",
                    }
                  )}
                </small>
              </div>
            ))
          ) : (
            <p>Nenhum comentário ainda. Seja o primeiro a comentar!</p>
          )}

          <div className="mt-3">
            <button
              className="btn btn-outline-primary"
              onClick={handleComentarioClick}
            >
              Deixar um comentário
            </button>
          </div>

          {showComentarioModal && (
            <div
              className="modal"
              style={{
                display: "block",
                backgroundColor: "rgba(0,0,0,0.5)",
                position: "fixed",
                top: 0,
                left: 0,
                right: 0,
                bottom: 0,
                zIndex: 1050,
              }}
            >
              <div className="modal-dialog modal-dialog-centered">
                <div className="modal-content">
                  <div className="modal-header">
                    <h5 className="modal-title">Novo Comentário</h5>
                    <button
                      type="button"
                      className="btn-close"
                      onClick={() => setShowComentarioModal(false)}
                    ></button>
                  </div>
                  <div className="modal-body">
                    <div className="mb-3">
                      <label htmlFor="nome" className="form-label">
                        Seu Nome
                      </label>
                      <input
                        type="text"
                        className="form-control"
                        id="nome"
                        value={nome}
                        onChange={(e) => setNome(e.target.value)}
                        placeholder="Digite seu nome"
                      />
                    </div>
                    <div className="mb-3">
                      <label htmlFor="email" className="form-label">
                        Seu E-mail
                      </label>
                      <input
                        type="email"
                        className="form-control"
                        id="email"
                        value={email}
                        onChange={(e) => setEmail(e.target.value)}
                        placeholder="Digite seu e-mail"
                      />
                    </div>
                    <div className="mb-3">
                      <label htmlFor="comentario" className="form-label">
                        Comentário
                      </label>
                      <textarea
                        className="form-control"
                        id="comentario"
                        rows="4"
                        value={novoComentario}
                        onChange={(e) => setNovoComentario(e.target.value)}
                        placeholder="Escreva seu comentário aqui..."
                      ></textarea>
                    </div>
                  </div>
                  <div className="modal-footer">
                    <button
                      type="button"
                      className="btn btn-secondary"
                      onClick={() => setShowComentarioModal(false)}
                    >
                      Cancelar
                    </button>
                    <button
                      type="button"
                      className="btn btn-primary"
                      onClick={handleSubmitComentario}
                      disabled={
                        !novoComentario.trim() || !nome.trim() || !email.trim()
                      }
                    >
                      Enviar
                    </button>
                  </div>
                </div>
              </div>
            </div>
          )}
        </div>
        <div className="col-md-6 bg-white p-4 rounded shadow">
          <div className="list-group">
            <button
              className="list-group-item list-group-item-action border-0 text-start p-0 mb-2"
              onClick={() => navigate("/cursos")}
              style={{
                background: "none",
                border: "none",
                textDecoration: "underline",
                color: "#0d6efd",
                cursor: "pointer",
              }}
            >
              📦 Cursos
            </button>
            <button
              className="list-group-item list-group-item-action border-0 text-start p-0 mb-2"
              onClick={() => handleProtectedLink("/aulas-ao-vivo")}
              style={{
                background: "none",
                border: "none",
                textDecoration: "underline",
                color: "#0d6efd",
                cursor: "pointer",
              }}
            >
              📚 Aulas ao Vivo
            </button>
            <button
              className="list-group-item list-group-item-action border-0 text-start p-0 mb-2"
              onClick={() => handleProtectedLink("/aulas-gravadas")}
              style={{
                background: "none",
                border: "none",
                textDecoration: "underline",
                color: "#0d6efd",
                cursor: "pointer",
              }}
            >
              📺 Aulas Gravadas
            </button>
            <button
              className="list-group-item list-group-item-action border-0 text-start p-0"
              onClick={() => handleProtectedLink("/material")}
              style={{
                background: "none",
                border: "none",
                textDecoration: "underline",
                color: "#0d6efd",
                cursor: "pointer",
              }}
            >
              📂 Material de Apoio
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

function getEmojiForArea(area) {
  const emojis = {
    Economia: "📉",
    Programacao: "💻",
    Contabilidade: "📊",
    Ingles: "📖",
    Matematica: "🧮",
    Design: "🎨",
  };
  return emojis[area] || "📚";
}

function formatDate(dateString) {
  const options = { year: "numeric", month: "short", day: "numeric" };
  return new Date(dateString).toLocaleDateString("pt-PT", options);
}

export default Home;
